function parse(text:string):any{try{return JSON.parse(text);}catch{throw unavailable("Original native withdrawal proof is malformed");}}
export function nativePayoutBinding(r:NativeWithdrawalRow,scope:PayoutScope):PayoutBinding{
 const s=readPayoutScope(scope);if(r.currency!=="CNY"||r.merchant_identity_id!==s.merchantIdentityId||r.user_no!==s.userNo||(r.trade_merchant_no??undefined)!==s.tradeMerchantNo||sha(r.scope_canonical)!==r.scope_sha256||sha(r.admission_canonical)!==r.admission_sha256||sha(r.initial_profile_canonical)!==r.initial_profile_sha256||sha(r.frozen_canonical)!==r.frozen_digest)throw unavailable("Original payout binding unavailable");
 assertInitialPayoutScope(scope,r.scope_ref,r.scope_sha256);const old=parse(r.scope_canonical),a=parse(r.admission_canonical),f=parse(r.frozen_canonical),p=parse(r.initial_profile_canonical);
 if(old.kind!=="JOINPAY_PAYOUT_SERVER_SCOPE"||old.reference!==r.scope_ref||old.database!==s.database||old.runtimeUser!==s.runtimeUser||old.merchantIdentityId!==r.merchant_identity_id||old.userNo!==r.user_no
  ||a.kind!=="JOINPAY_WITHDRAWAL_BUSINESS_ADMISSION"||a.reference!==r.admission_ref||a.userId!==r.user_id||a.scopeReference!==r.scope_ref||a.scopeSha256!==r.scope_sha256||a.policy?.version!==r.policy_version||a.target?.destinationId!==r.destination_id||a.target?.revision!==r.destination_revision
  ||a.target?.fingerprint!==r.target_fingerprint||a.target?.receiverAccountNoEnc!==r.receiver_account_no_enc||a.target?.receiverNameEnc!==r.receiver_name_enc||p.kind!=="JOINPAY_PAYOUT_PROFILE_V1"||p.operation!=="SUBMIT"||p.profileId!==r.initial_profile_id||p.keyVersionRef!==r.initial_key_version_ref
  ||!old.acceptedProfiles?.some((x:any)=>x.operation==="SUBMIT"&&x.profileId===r.initial_profile_id&&x.profileSha256===r.initial_profile_sha256&&x.keyVersionRef===r.initial_key_version_ref)
  ||f.kind!=="JOINPAY_WITHDRAWAL_FROZEN_BASIS")throw unavailable("Original payout admission differs");
 const expected=frozenBody(r);if(JSON.stringify(expected)!==r.frozen_canonical)throw unavailable("Original frozen withdrawal facts differ");
 return Object.freeze({intentId:r.id,userId:r.user_id,merchantIdentityId:r.merchant_identity_id,userNo:r.user_no,...(r.trade_merchant_no===null?{}:{tradeMerchantNo:r.trade_merchant_no}),merchantOrderNo:r.merchant_order_no,
  receiverAccountNoEnc:r.receiver_account_no_enc,receiverNameEnc:r.receiver_name_enc,netCents:r.net_cents,grossCents:r.gross_cents,feeCents:r.fee_cents,currency:"CNY",targetFingerprint:r.target_fingerprint,
  receiverAccountType:a.target.receiverAccountType,...(a.target.receiverBankChannelNo===undefined?{}:{receiverBankChannelNo:a.target.receiverBankChannelNo}),initialProfileId:r.initial_profile_id,initialProfileSha256:r.initial_profile_sha256,initialKeyVersionRef:r.initial_key_version_ref,
  encodingRuleRef:a.target.encodingRuleRef,encodingRuleSha256:a.target.encodingRuleSha256,encodingImplementationRef:a.target.encodingImplementationRef,encodingImplementationSha256:a.target.encodingImplementationSha256,targetEchoRuleRef:a.target.targetEchoRuleRef,targetEchoRuleSha256:a.target.targetEchoRuleSha256,
  ...(r.platform_serial_no?{platformSerialNo:r.platform_serial_no}:{})});
}
